import itertools
from typing import Iterable, Optional, Dict

class SearchArray:
    def index(cls, array: Iterable, tokenizer=ws_tokenizer,
              truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':

        # Initialize term dictionary, postings, and document lengths
        term_dict = {}
        postings = {}
        doc_lens = {}

        # Initialize average document length
        avg_doc_len = 0

        # Process the array in batches if necessary
        for batch in itertools.zip_longest(*[iter(array)] * batch_size):
            # Tokenize the strings in the batch using the specified tokenizer
            batch_tokens = [tokenizer(string) for string in batch if string is not None]

            # Update the term dictionary
            for tokens in batch_tokens:
                for token in tokens:
                    if token not in term_dict:
                        term_dict[token] = len(term_dict)

            # Update the postings and document lengths
            for i, tokens in enumerate(batch_tokens):
                for token in tokens:
                    if token not in postings:
                        postings[token] = []
                    postings[token].append(i)
                doc_lens[i] = len(tokens)

            # Update the average document length
            avg_doc_len = (avg_doc_len * (i + 1) + len(batch_tokens)) / (i + 2)

        # Create a new instance of SearchArray
        search_array = cls.__init__(postings, 
                                    doc_len=len(array),
                                    posns=term_dict,
                                    encoded=False)

        # Return the instance of SearchArray
        return search_array

class SearchArray:
    def __init__(self,
                 postings: Dict,
                 doc_len: int = 0,
                 posns: Optional[Dict] = None,
                 encoded=False):
        self.postings = postings
        self.doc_lens = doc_lens
        self.term_dict = term_dict
        self.avg_doc_len = avg_doc_len

# Define the ws_tokenizer function
def ws_tokenizer(string):
    return string.split()
